dataConfig.script:
                function TransformAuthor(row)    {
                    var firstName = row.get('FIRST_NAME');
                    var lastName = row.get('LAST_NAME');
                    var degrees = row.get('DEGREE_LETTERS');
                    var author = '';
                    if(firstName != null){
                        author += firstName;
                    }
					if(lastName != null){
                        author += (((firstName != null) ? ' ' : '' ) +lastName);
                    }
                                        var shortAuthor = author;
					if(degrees != null){
                        author += (', ' +degrees);
                    }
                    row.put('shortAuthor', shortAuthor);
                    row.put('author', author);
                    return row;
                }
                function TransformOrigin(row){
                    var origin = row.get('LARGE_STRING_VALUE');
					row.put('contactOriginRelevancy', parseFloat((origin == '"US"') ? "1.0" : "0.0"));
					return row;
				}
				function TransformFormats(row)    {
					var JSON={};
                    var platformString = row.get('LARGE_STRING_VALUE');
					var ArrayList = Java.type('java.util.ArrayList');
					var platformkeys = new ArrayList();
					if(platformString!= null){
					    var parsablePlatfromString = "(" + platformString.toString() + ")";
						var platforms= eval(parsablePlatfromString);
						
						for (var k in platforms){
							platformkeys.add(k);
						}
					}
                    row.put('availableFormat', platformkeys);
                    return row;
                }
				function TransformAuthors(row){
					if(authorHtml != ""){
						row.put('authorHtml', authorHtml);
					}
					return row;
				}

				function TransformPriceAndEdition(row){
					var evolvePrice = row.get('PRICE');
					var ppmPrice = row.get('PPM_PRICE');
					var ppmPriceCAD = row.get('PPM_PRICE_CAD');
					var edition = row.get('EDITION_NUMBER');
					
					if(ppmPriceCAD == null){
						ppmPriceCAD = "0.0";
					}
					
					if(evolvePrice == null){
						evolvePrice = ppmPrice;
					}
					
                    if(evolvePrice == null){
						evolvePrice = "0.0";
					}
					
                    if(edition == null){
						edition = "1.0";
					}
					
					row.put('listPrice',parseFloat(evolvePrice));
					row.put('listPriceCAD',parseFloat(ppmPriceCAD));
                    row.put('edition', parseFloat(edition));
					return row;
				}
                                function GenerateFacultyPrice(row){
					var facultyPrice = row.get('ORIGINAL_PRICE');
					var facultyPriceCAD = row.get('ORIGINAL_PRICE_CAD');
					var productType = row.get('PRODUCT_TYPE_KEY');
					var eFlag = row.get('EFLAG');
					if(eFlag == "Y") {
						if (productType.toLowerCase().indexOf("ebook") == -1) {
							facultyPrice = "0.0";
							facultyPriceCAD = "0.0";
						}
					}
					row.put('facultyPrice', parseFloat(facultyPrice));
					row.put('facultyPriceCAD', parseFloat(facultyPriceCAD));
					return row;
				}
                                function TransformDiscSpec(row){
					var discId = row.get('DISCIPLINE_ID');
					var specId = row.get('SPECIALTY_ID');
					var category_id = "ds_";
					if(discId != null){
						category_id += discId;
					}
					if(specId != null){
						category_id += ("_" + specId);
					}
					row.put('category_id', category_id);
					return row;
				}
                                function TransformProgramTaxonomySpec(row){
					var categoryId = row.get('PROGRAM_CATEGORY_ID');
					var categorySubId = row.get('PROGRAM_SUB_CATEGORY_ID');
					var programCategoryId = "pc_";
					if(categoryId != null){
						programCategoryId += categoryId;
					}
					if(categorySubId != null){
						programCategoryId += ("_" + categorySubId);
					}
					row.put('programCategoryId', programCategoryId);
					return row;
				}
				function TransformRelatedProductResourceDetailsSpec(row){
					var resourceKey = row.get('RESOURCE_KEY');
					var name = row.get('NAME');
					var resourceTypeKey = row.get('RESOURCE_TYPE_KEY');
					var productTypeKey = row.get('PRODUCT_TYPE_KEY');
					var catalogProductTypeKey = row.get('CATALOG_PRODUCT_TYPE_KEY');
					var editionNumber = row.get('EDITION_NUMBER');
					var copyRightYear = row.get('COPYRIGHT_YEAR');
					var relevancy = row.get('RELEVANCY');
					var role = row.get('ROLE');

					var evolvePrice = row.get('PRICE');
					var ppmPrice = row.get('PPM_PRICE');
					var ppmPriceCAD = row.get('PPM_PRICE_CAD');

					if(ppmPriceCAD == null){
						ppmPriceCAD = "0.0";
					}

					if(evolvePrice == null){
						evolvePrice = ppmPrice;
					}

                    if(evolvePrice == null){
						evolvePrice = "0.0";
					}

					var relatedProductResourceDetails = "";
					if(resourceKey != null){
						relatedProductResourceDetails += (resourceKey + ";");
					}
					if(name != null){
						relatedProductResourceDetails += (name + ";");
					}
					if(resourceTypeKey != null){
						relatedProductResourceDetails += (resourceTypeKey + ";");
					}
					if(productTypeKey != null){
						relatedProductResourceDetails += (productTypeKey + ";");
					}
					if(catalogProductTypeKey != null){
						relatedProductResourceDetails += (catalogProductTypeKey + ";");
					}
					if(editionNumber != null){
						relatedProductResourceDetails += (editionNumber + ";");
					}
					if(copyRightYear != null){
						relatedProductResourceDetails += (copyRightYear + ";");
					}
					if(evolvePrice != null){
						relatedProductResourceDetails += (parseFloat(evolvePrice) + ";");
					}
					if(ppmPriceCAD != null){
						relatedProductResourceDetails += (parseFloat(ppmPriceCAD) + ";");
					}
					if(relevancy != null){
						relatedProductResourceDetails += (relevancy + ";");
					}
					if(role != null){
						relatedProductResourceDetails += (role);
					}
					row.put('relatedProductDetails', relatedProductResourceDetails);
					return row;
				}
